const raw = items[0].json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const eventType = body.event_type || body.event || 'unknown';
const guardianPhone = body.guardian_contact || body.guardian_phone || body.student_contact || '';
const guardianEmail = body.guardian_email || '';
const studentEmail = body.student_email || '';
const studentName = body.student_name || 'Student';
const caseCode = body.case_code || (body.case_id ? `Case #${body.case_id}` : 'N/A');
const violation = body.violation_title || 'School violation';
const severity = body.violation_severity || body.severity || 'N/A';
const sanction = body.sanction || 'To be determined';
const department = body.department || 'N/A';
const hours = body.required_hours || body.hours_served || '';
const closedAt = body.closed_at || '';
const scheduledAt = body.scheduled_at || '';
const venue = body.venue || '';

let subject = `[VioTrack] Update — ${caseCode}`;
let emailText = '';
let smsText = '';
let stage = eventType;

switch (eventType) {
  case 'violation_recorded':
    subject = `[VioTrack] Violation recorded — ${studentName}`;
    emailText = `Good day,\n\nA school violation was recorded for ${studentName} (${department}).\n\nCase: ${caseCode}\nViolation: ${violation}\nSeverity: ${severity}\nRecommended sanction: ${sanction}\n\nPlease coordinate with the Office of Student Affairs / Dean as needed.\n\n— VioTrack · I-Link CST`;
    smsText = `I-Link CST: Violation recorded for ${studentName} (${violation}). Case ${caseCode}. Check VioTrack / contact OSA.`;
    stage = '1 · Violation recorded';
    break;
  case 'hearing_scheduled':
    subject = `[VioTrack] Hearing scheduled — ${studentName}`;
    emailText = `Good day,\n\nA hearing has been scheduled for ${studentName}.\n\nCase: ${caseCode}\nViolation: ${violation}\nWhen: ${scheduledAt || 'TBA'}\nVenue: ${venue || 'TBA'}\n\nPlease arrive on time / ensure the guardian is informed.\n\n— VioTrack · I-Link CST`;
    smsText = `I-Link CST: Hearing for ${studentName} on ${scheduledAt || 'TBA'} at ${venue || 'TBA'}. Case ${caseCode}.`;
    stage = '2 · Hearing scheduled';
    break;
  case 'gso_sanction_assigned':
    subject = `[VioTrack] Community service assigned — ${studentName}`;
    emailText = `Good day,\n\nCommunity service hours were assigned for ${studentName}.\n\nCase: ${caseCode}\nSanction: ${sanction}\nRequired hours: ${hours || 'N/A'}\n\nGSO will monitor DTR compliance in VioTrack.\n\n— VioTrack · I-Link CST`;
    smsText = `I-Link CST: ${studentName} assigned ${hours || ''} hr community service. Case ${caseCode}. GSO will monitor DTR.`;
    stage = '3 · GSO hours assigned';
    break;
  case 'gso_sanction_completed':
    subject = `[VioTrack] GSO completed — ready for OSA — ${studentName}`;
    emailText = `Good day, OSA team,\n\nGSO marked community service COMPLETE for ${studentName}.\n\nCase: ${caseCode}\nHours served: ${hours || 'N/A'}\nSanction: ${sanction}\n\nThe DTR record was forwarded for the next OSA step (review / close case).\n\n— VioTrack · I-Link CST`;
    smsText = `I-Link CST: GSO completed hours for ${studentName}. Case ${caseCode}. Ready for OSA next step.`;
    stage = '4 · GSO completed → OSA';
    break;
  case 'case_closed':
    subject = `[VioTrack] Case closed — ${studentName}`;
    emailText = `Good day,\n\nThe case for ${studentName} has been officially closed.\n\nCase: ${caseCode}\nViolation: ${violation}\nSanction served: ${sanction}\nClosed at: ${closedAt || 'N/A'}\n\nThank you for your cooperation.\n\n— VioTrack · I-Link CST`;
    smsText = `I-Link CST: Case ${caseCode} for ${studentName} is CLOSED. Sanction: ${sanction}.`;
    stage = '5 · Case closed';
    break;
  default:
    subject = `[VioTrack] Event: ${eventType}`;
    emailText = `Event ${eventType} received for ${studentName}. Case ${caseCode}.`;
    smsText = `I-Link CST: ${eventType} for ${studentName}. Case ${caseCode}.`;
    stage = `Other · ${eventType}`;
}

return [{
  json: {
    event_type: eventType,
    stage,
    subject,
    email_text: emailText,
    sms_text: smsText,
    guardian_email: guardianEmail,
    student_email: studentEmail,
    notify_email: guardianEmail || studentEmail,
    guardian_phone: String(guardianPhone || '').replace(/\s+/g, ''),
    student_name: studentName,
    case_code: caseCode,
    violation_title: violation,
    sanction,
    department,
    timestamp: body.timestamp || new Date().toISOString(),
    raw: body
  }
}];

const item = items[0].json;
return [{
  json: {
    ok: true,
    stage: item.stage || item.pipeline_label,
    event_type: item.event_type,
    student_name: item.student_name,
    case_code: item.case_code,
    notified_email: item.notify_email || null,
    notified_phone: item.guardian_phone || null,
    presented_at: new Date().toISOString(),
    message: 'VioTrack automation executed successfully'
  }
}];
